#include <iostream>
#include <memory>
#include <unordered_map>
#include <functional>
struct MyData { int x; };
template <class T, class D> struct std::hash<std::unique_ptr<T, D>> {
  std::size_t operator()(const std::unique_ptr<T, D>& ptr) const {
    return std::hash<T*>()(ptr.get());
  }
};
int main() {
  std::unordered_map<std::unique_ptr<MyData>, int, std::hash<std::unique_ptr<MyData>>> myMap;
  auto ptr1 = std::make_unique<MyData>(); ptr1->x = 10;
  auto ptr2 = std::make_unique<MyData>(); ptr2->x = 20;
  myMap[std::move(ptr1)] = 1;
  myMap[std::move(ptr2)] = 2;
  std::cout << myMap[std::unique_ptr<MyData>(new MyData{10})] << std::endl; //Will not work reliably without proper hash specialization
  std::cout << myMap.size() << std::endl;
  return 0;
}
